import{c as o,Q as r,j as i,m as t}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"Rust Crates","description":"","frontmatter":{},"headers":[],"relativePath":"developers/crates.md","filePath":"developers/crates.md","lastUpdated":null}'),s={name:"developers/crates.md"};function a(c,e,n,d,l,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="rust-crates" tabindex="-1">Rust Crates <a class="header-anchor" href="#rust-crates" aria-label="Permalink to &quot;Rust Crates&quot;">​</a></h1><h2 id="finsight-core" tabindex="-1">finsight-core <a class="header-anchor" href="#finsight-core" aria-label="Permalink to &quot;finsight-core&quot;">​</a></h2><ul><li><strong>DB</strong> (<code>db.rs</code>) — r2d2 pool over SQLCipher, per-user connection.</li><li><strong>Migrations</strong> (<code>migrations/V00N__*.sql</code>, Refinery) — discovered via <code>embed_migrations!</code>, currently through V016.</li><li><strong>Models</strong> (<code>models/*</code>) — <code>Transaction</code>, <code>Category</code>, <code>Account</code>, <code>Goal</code>, <code>BudgetEnvelope</code>, <code>ReportWidget</code>, etc.</li><li><strong>Repos</strong> (<code>repos/*</code>) — SQL lives here (e.g. <code>transactions.rs</code>, <code>budgets.rs</code>, <code>goals.rs</code>, <code>agent_memory.rs</code>).</li><li><strong>Metrics / Forecast / Cashflow</strong> (<code>metrics.rs</code>, <code>forecast.rs</code>, <code>cashflow.rs</code>) — deterministic finance math shared by every screen and the Copilot.</li><li><strong>Categorize / Anomaly / Recurring</strong> (<code>categorize.rs</code>, <code>anomaly.rs</code>, <code>recurring.rs</code>, <code>subscriptions.rs</code>) — deterministic classifiers and detectors.</li><li><strong>Currency</strong> (<code>currency.rs</code>) — unconverted holdings bucket; no invented rates.</li><li><strong>Crypto</strong> (<code>crypto.rs</code> in <code>finsight-server</code>, not core) — but core owns the DB file that wraps keys describe.</li></ul><h2 id="finsight-providers" tabindex="-1">finsight-providers <a class="header-anchor" href="#finsight-providers" aria-label="Permalink to &quot;finsight-providers&quot;">​</a></h2><p>CSV parsers + <code>CompletionProvider</code> trait (<code>providers/openai_compat.rs</code>, <code>providers/ollama.rs</code>, <code>providers/anthropic.rs</code>). Each provider is a thin HTTP client; the trait lets <code>finsight-agent</code> not know which is configured.</p><h2 id="finsight-agent" tabindex="-1">finsight-agent <a class="header-anchor" href="#finsight-agent" aria-label="Permalink to &quot;finsight-agent&quot;">​</a></h2><ul><li><code>context.rs</code> — builds <code>FinancialContext</code> + <code>WellnessContext</code> for every Copilot call.</li><li><code>planner.rs</code> — <code>build_system_prompt</code>, <code>plan</code>, <code>persist_plan</code> (<code>ACTION_KINDS</code> allow-list).</li><li><code>executor.rs</code> — runs the plan via <code>ApiState</code>.</li><li><code>categorizer.rs</code> / <code>anomaly.rs</code> / <code>recipe_runner.rs</code> / <code>navigation.rs</code> — agent subsystems.</li><li><code>providers/*</code> + <code>reasoning/*</code> — LLM streaming, reasoning blocks, and typed gen-UI bindings.</li></ul><h2 id="finsight-api" tabindex="-1">finsight-api <a class="header-anchor" href="#finsight-api" aria-label="Permalink to &quot;finsight-api&quot;">​</a></h2><p>Transport-agnostic handlers + <code>ApiState</code>. Each handler is a pure function over the database; it does not know HTTP vs tests.</p><h2 id="finsight-openapi" tabindex="-1">finsight-openapi <a class="header-anchor" href="#finsight-openapi" aria-label="Permalink to &quot;finsight-openapi&quot;">​</a></h2><p>Typed OpenAPI spec via utoipa (<code>COMMANDS</code> + <code>build_openapi()</code>). Source of truth for <code>openapi.json</code> generation.</p><h2 id="finsight-server" tabindex="-1">finsight-server <a class="header-anchor" href="#finsight-server" aria-label="Permalink to &quot;finsight-server&quot;">​</a></h2><p>Axum server: auth (cookies, rotation, throttling, sessions), routing, CSV uploads, SSE, static UI, per-user runtime eviction. Owns <code>users.db</code> and <code>session.key</code> on disk.</p><p>See also: <a href="/FinSight/developers/api">API &amp; RPC</a>, <a href="/FinSight/developers/bindings">OpenAPI Bindings</a>.</p>',14)])])}const u=o(s,[["render",a]]);export{g as __pageData,u as default};
